timeout 110 bash -c 'export CREW_AGENT=lead CREW_LANE='"'"'acceptance.3'"'"' CREW_WORKSPACE='"'"'f314878f2da05337c6bfdc69730613787d36c12fc7dff9d3e340c716ed59c438'"'"' CREW_INSTALL_TRACE_STEP='"'"'lead-585 Final custody: enumerate live daemon/own controls separately from all defunct entries, require no unexpected live app/browser'"'"'; node --input-type=module -e '"'"'import {readdir,readFile} from '"'"'"'"'"'"'"'"'node:fs/promises'"'"'"'"'"'"'"'"';
const records=[],disappeared=[];
for(const name of await readdir('"'"'"'"'"'"'"'"'/proc'"'"'"'"'"'"'"'"')){
 if(!/^\d+$/.test(name))continue;
 try{const stat=await readFile('"'"'"'"'"'"'"'"'/proc/'"'"'"'"'"'"'"'"'+name+'"'"'"'"'"'"'"'"'/stat'"'"'"'"'"'"'"'"','"'"'"'"'"'"'"'"'utf8'"'"'"'"'"'"'"'"'),end=stat.lastIndexOf('"'"'"'"'"'"'"'"') '"'"'"'"'"'"'"'"'),fields=stat.slice(end+2).trim().split(/\s+/);records.push({pid:Number(name),ppid:Number(fields[1]),state:fields[0],comm:stat.slice(stat.indexOf('"'"'"'"'"'"'"'"'('"'"'"'"'"'"'"'"')+1,end)});}
 catch(error){if(['"'"'"'"'"'"'"'"'ENOENT'"'"'"'"'"'"'"'"','"'"'"'"'"'"'"'"'ESRCH'"'"'"'"'"'"'"'"'].includes(error.code))disappeared.push(Number(name));else throw error;}
}
