let parent=process.ppid;
while(parent>1&&!ancestors.has(parent)){ancestors.add(parent);parent=byPid.get(parent)?.ppid??0;}
const defunct=records.filter(r=>r.state==='"'"'"'"'"'"'"'"'Z'"'"'"'"'"'"'"'"'),controls=records.filter(r=>r.state!=='"'"'"'"'"'"'"'"'Z'"'"'"'"'"'"'"'"'&&ancestors.has(r.pid)),daemon=records.filter(r=>r.pid===1&&r.state!=='"'"'"'"'"'"'"'"'Z'"'"'"'"'"'"'"'"'),unexpected=records.filter(r=>r.state!=='"'"'"'"'"'"'"'"'Z'"'"'"'"'"'"'"'"'&&r.pid!==1&&!ancestors.has(r.pid));
const result={kind:'"'"'"'"'"'"'"'"'lead-final-process-audit'"'"'"'"'"'"'"'"',atUTC:new Date().toISOString(),records:records.length,liveUnexpected:unexpected,liveControls:controls,daemon,defunctCount:defunct.length,defunct,disappeared};
console.log(JSON.stringify(result));if(unexpected.length)process.exitCode=1;
